use minisign_verify::{PublicKey, Signature};
fn main() {
 let args:Vec<String>=std::env::args().collect(); assert_eq!(args.len(),5);
 let public=PublicKey::decode(&std::fs::read_to_string(&args[1]).unwrap()).unwrap();
 let text=std::fs::read_to_string(&args[2]).unwrap(); let signature=Signature::decode(&text).unwrap();
 let mut bytes=std::fs::read(&args[3]).unwrap(); public.verify(&bytes,&signature,true).unwrap();
 let expected=format!("version:{}",args[4]);
 assert!(signature.trusted_comment().split('\t').any(|part|part==expected));
 let mid=bytes.len()/2; bytes[mid]^=1; assert!(public.verify(&bytes,&signature,true).is_err());
 let changed=text.replace(&expected,"version:0.0.0"); assert_ne!(changed,text);
 let wrong_version=Signature::decode(&changed).unwrap();
 let original=std::fs::read(&args[3]).unwrap(); assert!(public.verify(&original,&wrong_version,true).is_err());
 println!("{{\"signature_valid\":true,\"signed_version_matches\":true,\"modified_archive_rejected\":true,\"modified_signed_version_rejected\":true}}");
}
